export const BODY: string = "\n<p>التصميم هو القرار الأول في الكولاج، ويشكل كل ما يليه. الشبكة تقول إن الصور متساوية. الشريط يقول إنها تسلسل. ولوحة الإلهام تقول إنها إحساس.</p>\n<p>تقارن هذه المقالة التصاميم التي يقدمها صانع كولاج الصور: شبكات 2 في 2 و3 في 3 والشرائط العمودية والأفقية والأساليب الحرة المبنية منها، بما فيها لوحات الإلهام.</p>\n<p>اقرأها قبل بناء كولاجك التالي. التصميم المختار للغرض يجعل الكولاج يُقرأ فورًا، بينما المختار عشوائيًا يجعل المشاهد يعمل ليفهم ما يراه.</p>\n<h2 id=\"why-layout-matters\">لماذا يهم التصميم</h2>\n<p>التصميم هو ترتيب القراءة. العين تدخل الكولاج من أعلى اليسار وتتحرك عبر الصف العلوي ثم تنزل، كما تقرأ صفحة. والتصميم يقرر أي صورة تُرى أولًا وأيها تُرى أخيرًا.</p>\n<p>الشبكة تعطي كل صورة الوزن نفسه، فالمشاهد يمسح المجموعة كلها قبل التوقف. والشريط يعطي الصور تسلسلًا، فيتبعها المشاهد بالترتيب. كما يقرر التصميم شكل الصورة المكتملة: شبكة تعطي مربعًا وشريط عمودي يعطي عموديًا وشريط أفقي يعطي لافتة عريضة.</p>\n<h2 id=\"the-2x2-grid\">شبكة 2 في 2</h2>\n<p>شبكة 2 في 2 تحفظ أربع صور في مربع، وهي أبسط كولاج موجود. أربع خلايا متساوية وصورة مربعة واحدة ولا تسلسل هرمي لإدارته. إنها التصميم المفضل للمبتدئين.</p>\n<p>أربع صور تكفي لعرض مجموعة دون إرباك المشاهد. منتج بأربع زوايا أو غرفة بأربعة تفاصيل أو يوم بأربعة لحظات تناسب شبكة 2 في 2. كما أنها التصميم الأكثر مرونة للاتجاهات المختلطة، لأن كل خلية مربعة.</p>\n<h2 id=\"the-3x3-grid\">شبكة 3 في 3</h2>\n<p>شبكة 3 في 3 تحفظ تسع صور في مربع، وهي التصميم لمجموعة كاملة. رحلة أو حدث أو تشكيلة منتجات بتسع صور قوية تملأ الشبكة بنظرة واحدة.</p>\n<p>تسع صور تحتاج تسع صور قوية. شبكة بثلاث صور رائعة وست صور حشو تبدو أسوأ من شبكة 2 في 2 بأربع رائعات، لأن الصور الضعيفة تُرى بالحجم الكامل. والخلية المركزية هي نقطة التركيز الطبيعية، فالصورة الرئيسية تذهب إلى المنتصف أو أعلى اليسار.</p>\n<h2 id=\"vertical-strips\">الشرائط العمودية</h2>\n<p>الشريط العمودي يكدس الصور في عمود طويل يُقرأ من الأعلى إلى الأسفل. يناسب التسلسل: صباح وظهر ومساء، أو خطوة واحدة واثنتان وثلاث، أو رحلة من البداية إلى النهاية.</p>\n<p>الشرائط العمودية تناسب اللوحات العمودية، التي تناسب القصص وشاشات الهواتف. الكولاج الطويل يملأ شاشة الهاتف بشكل طبيعي. ومن ثلاث إلى خمس صور هو النطاق العملي: كافية لتسلسل وقليلة بما يكفي لتظل كل صورة مقروءة.</p>\n<h2 id=\"horizontal-strips\">الشرائط الأفقية</h2>\n<p>الشريط الأفقي يصطف الصور في صف عريض يُقرأ من اليسار إلى اليمين. يناسب خطًا زمنيًا أو بانوراما لحظات أو مقارنة يمسح فيها المشاهد جانبًا.</p>\n<p>الشرائط الأفقية تناسب اللوحات العريضة، التي تناسب اللافتات والترويسات والأقسام المميزة في مواقع الويب. والشريط يعمل جيدًا لمقارنات قبل وبعد، حيث تبقى صورتان أو ثلاث جنبًا إلى جنب ويظهر التغيير بنظرة واحدة. وأبقِ الشريط قصيرًا: صورتان إلى أربع هو النطاق العملي.</p>\n<h2 id=\"mood-boards\">لوحات الإلهام</h2>\n<p>لوحة الإلهام كولاج مبني حول إحساس لا حول حدث. تجمع ألوانًا وقوامًا وصورًا تشترك في مزاج: غرفة نوم هادئة أو علامة قوية أو موسم قادم.</p>\n<p>ابنِ لوحة إلهام من شبكة، عادة 3 في 3، بمزيج من الصور وعينات الألوان والقوام. التنوع هو المقصود: لقطة قريبة لقماش ومنظر طبيعي ولون جدار. واستخدم مساحة ولون خلفية متسقين للحفاظ على تماسك اللوحة، وإلا تفككت إلى صور عشوائية.</p>\n<h2 id=\"story-layouts\">تصاميم القصة</h2>\n<p>تصميم القصة كولاج مرتب كسرد: بداية وتطور ونهاية. يستخدم شريطًا أو شبكة بترتيب قراءة واضح، فيتبع المشاهد القصة دون جهد.</p>\n<p>استخدم شريطًا عموديًا لقصة تُروى في الزمن، بالبداية في الأعلى والنهاية في الأسفل. رحلة يوم أو وصفة أو بناء مشروع تُقرأ بشكل طبيعي نحو الأسفل. واستخدم شبكة بصورة مميزة لقصة تُروى حول لحظة: الصورة المميزة هي الذروة والصور الأصغر هي السياق.</p>\n<h2 id=\"before-and-after-layouts\">تصاميم قبل وبعد</h2>\n<p>كولاج قبل وبعد يعرض تغييرًا، ويجب أن يجعل التصميم التغيير واضحًا. الشريط الأفقي هو الخيار الطبيعي: قبل على اليسار وبعد على اليمين، والمشاهد يمسح التغيير ويراه فورًا.</p>\n<p>استخدم صورتين فقط، أو ثلاث مع خطوة وسيطة. قبل وبعد بتسع صور يدفن التغيير في شبكة، بينما صورتان جنبًا إلى جنب تجعلان تجاهله مستحيلًا. وساوِ تأطير الصورتين: الزاوية نفسها والقص نفسه والإضاءة نفسها تجعل التغيير يبرز. ووسّم الصور عندما يكون التغيير خفيفًا باستخدام <a href=\"/ar/idafa-nass-ila-as-sura/\">إضافة نص إلى صورة</a>.</p>\n<h2 id=\"feature-photo-layouts\">تصاميم بصورة مميزة</h2>\n<p>تصميم الصورة المميزة يكبّر خلية فوق البقية، معطيًا الكولاج نقطة تركيز واضحة. العين تصل أولًا إلى الصورة الكبيرة، ثم تستكشف الأصغر، ما يعطي الكولاج تسلسلًا هرميًا.</p>\n<p>ابنِه بضبط التقسيمات في شبكة، مكبرًا الخلية الرئيسية ومصغرًا جيرانها. واختر المميزة بالجودة إضافة إلى الموضوع: يجب أن تكون الرئيسية أحدة صورة وأسطوعها في المجموعة، لأن تكبير صورة ضعيفة يجذب الانتباه إلى عيوبها فقط. وأبقِ المميزة صورة واحدة.</p>\n<h2 id=\"borderless-collages\">كولاج دون حدود</h2>\n<p>الكولاج دون حدود يضع المساحة صفرًا، فتتلامس الصور وتشكل صورة واحدة متصلة. يناسب المجموعات حيث تشترك الصور في مشهد أو لوحة ألوان، لأن الحدود المختفية تجعلها تندمج.</p>\n<p>دون حدود يعمل أفضل عندما تكون الصور متشابهة في النغمة. مجموعة صور شاطئ بنفس الإضاءة تندمج في بانوراما لحظات، بينما مجموعة صور مختلطة دون مساحة تبدو مزدحمة. واستخدم تصميمًا دون حدود لتأثير جدار صور، حيث يجب أن يبدو الكولاج صورة كبيرة مصنوعة من قطع.</p>\n<h2 id=\"mixing-orientations\">كيف تخلط الاتجاهات</h2>\n<p>الكولاج يخلط غالبًا صورًا عمودية وأفقية، ويجب أن يتعامل التصميم مع الخليط. الشبكات تتعامل معه أفضل، لأن كل خلية مربعة وملاءمة التغطية تقص كل صورة لتناسب.</p>\n<p>الشرائط تتعامل مع الاتجاهات المختلطة بشكل أسوأ. صورة عمودية في شريط أفقي تصبح خلية عالية في صف عريض، ما يخل بتوازن الشريط. وعندما يكون الخليط قويًا، استخدم شبكة ودع الملاءمة تقوم بالعمل، وراجع كل خلية للقص السيئ. وبدلًا من ذلك، قص الصور إلى اتجاه متسق قبل بناء الكولاج باستخدام <a href=\"/ar/qass-as-suwar/\">قاص الصور</a>.</p>\n<h2 id=\"choosing-a-layout-for-the-purpose\">كيف تختار تصميمًا حسب الغرض</h2>\n<p>طابق التصميم مع الوجهة أولًا. منشور خلاصة يريد شبكة مربعة، وقصة تريد شريطًا عموديًا، ولافتة تريد شريطًا أفقيًا. الشكل الذي تحتاجه الوجهة يضيّق الخيارات فورًا.</p>\n<p>ثم طابق التصميم مع القصة: لحظات متساوية تريد شبكة، وتسلسل يريد شريطًا، ولحظة رئيسية تريد تصميمًا مميزًا، وإحساس يريد لوحة إلهام. وأخيرًا طابق التصميم مع عدد الصور: أربع صور تريد شبكة 2 في 2، وتسع تريد 3 في 3، واثنتان تريدان شريطًا.</p>\n<h2 id=\"quick-reference\">مرجع سريع: خيارات التصميم</h2>\n<p>لحظات متساوية: شبكة 2 في 2 أو 3 في 3. تسلسل: شريط عمودي للزمن، وشريط أفقي للمقارنة. لحظة رئيسية: تصميم بصورة مميزة. إحساس: لوحة إلهام.</p>\n<p>طابق الشكل مع الوجهة والتصميم مع القصة والتصميم مع عدد الصور. وابنِ تصميمين وقارنهما بحجم الصورة المصغرة عندما لا تكون متأكدًا.</p>\n<p>للإنشاء خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-ins-ha-kulaj-suwar/\">كيف تصنع كولاج صور</a>، وللدليل الكامل اقرأ <a href=\"/ar/blog/dalil-munshi-kulaj-as-suwar/\">صانع كولاج الصور: الدليل الكامل</a>. وأنشئ كولاجك مع <a href=\"/ar/munshi-kulaj-as-suwar/\">صانع كولاج الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"أي تصميم كولاج أفضل لوسائل التواصل؟","answer":"الشبكة المربعة، 2 في 2 أو 3 في 3، هي الخيار الآمن لمنشور خلاصة، لأنها تناسب الشبكة وتُقرأ بحجم الصورة المصغرة. الشريط العمودي يناسب القصص، حيث تملأ الصورة الطويلة الشاشة."},{"question":"ما هو كولاج لوحة الإلهام؟","answer":"لوحة الإلهام كولاج مبني حول إحساس لا حول حدث. تجمع ألوانًا وقوامًا وصورًا تشترك في مزاج، عادة في شبكة 3 في 3 بمساحة ولون خلفية متسقين. إنها أداة عمل للمصممين والمنسقين والمخططين."},{"question":"كيف أجعل صورة تبرز في كولاج؟","answer":"كبّر خليتها بضبط التقسيمات، فتكون أكبر بوضوح من البقية. واختر أحدة صورة وأسطوعها كمميزة، وأبقها صورة واحدة: خليتان كبيرتان تتنافسان ويتكسر التسلسل الهرمي."},{"question":"هل الكولاج دون حدود أفضل من الكولاج بمساحات؟","answer":"لا أحدهما أفضل عمومًا. المساحة صفر تناسب صورًا تشترك في مشهد أو لوحة ألوان، لأن الكولاج يُقرأ كصورة متصلة. والمساحة المرئية تناسب صورًا مختلطة، لأنها تفصل كل صورة عن جارتها."},{"question":"أي تصميم يعمل أفضل لصور قبل وبعد؟","answer":"شريط أفقي بصورتين: قبل على اليسار وبعد على اليمين. يمسح المشاهد التغيير ويراه فورًا. وساوِ التأطير والزاوية والإضاءة في الصورتين لتكون المقارنة صادقة."},{"question":"هل يمكنني استخدام تصميم كولاج لقصة أو غلاف ريل؟","answer":"نعم، شريط عمودي على لوحة عمودية يناسب قصة، وشبكة مربعة تناسب غلاف ريل. ابنِ الكولاج بالنسبة التي تحتاجها الوجهة، وأبقِ الموضوع متمركزًا واترك مساحة لواجهة المنصة."}];
